using System.Text.Json; using System.Text.RegularExpressions; using GSPTaskMiningAnalyzer.Models;
namespace GSPTaskMiningAnalyzer;
public sealed record ActivityRule(string Activity,string? Process,string? TitleRegex,string? Category=null,string? ProcessGroup=null);
public sealed class ActivityRules{ public List<ActivityRule> Rules{get;set;}=[]; public static ActivityRules Load(string? path=null){path ??= Path.Combine(AppContext.BaseDirectory,"activity-rules.json"); if(!File.Exists(path)) return new(); return JsonSerializer.Deserialize<ActivityRules>(File.ReadAllText(path),new JsonSerializerOptions{PropertyNameCaseInsensitive=true})??new();} public (string name,string cat,string grp) Match(LogEvent e){foreach(var r in Rules){ if(!string.IsNullOrEmpty(r.Process)&&!string.Equals(r.Process,e.ProcessName,StringComparison.OrdinalIgnoreCase)) continue; if(!string.IsNullOrEmpty(r.TitleRegex)&&!Regex.IsMatch(e.WindowTitle??"",r.TitleRegex,RegexOptions.IgnoreCase)) continue; return (r.Activity,r.Category??"Операция",r.ProcessGroup??(r.Process??e.ProcessName));} return ($"{e.ProcessName}: {e.WindowTitle}".Trim(' ',':'),"Не классифицировано",string.IsNullOrWhiteSpace(e.ProcessName)?"unknown":e.ProcessName);} }
